def math_agent(expr):
    return {"agent": "math", "result": eval(expr)}

def weather_agent(city):
    return {"agent": "weather", "result": f"{city}: 22C, sunny"}

def greet_agent(name):
    return {"agent": "greet", "result": f"Hello {name}, how can I help?"}

def route(sub_task):
    if sub_task.startswith("calc:"):
        arg = sub_task.split(":", 1)[1].strip()
        return math_agent(arg)
    elif sub_task.startswith("weather:"):
        arg = sub_task.split(":", 1)[1].strip()
        return weather_agent(arg)
    elif sub_task.startswith("greet:"):
        arg = sub_task.split(":", 1)[1].strip()
        return greet_agent(arg)
    return {"agent": "unknown", "result": "Unknown command"}

def coordinator_agent(task):
    if " and " in task:
        parts = task.split(" and ")
        results = [route(p.strip()) for p in parts]
        return {"task": task, "results": results, "status": "ok"}
    else:
        result = route(task)
        return {"task": task, "results": [result], "status": "ok" if result["agent"] != "unknown" else "error"}
